import{_ as s,a0 as i,w as r,s as h,ao as d,I as e,x as t,a1 as o,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Java 与 Python：你应该选择哪个？ | LCTT x X-CMD","titleTemplate":false,"description":"Java 与 Python：你应该选择哪个？ | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Java 与 Python：你应该选择哪个？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Java 与 Python：你应该选择哪个？ | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191204 Java vs. Python- Which should you choose","title":"Java 与 Python：你应该选择哪个？","tag":"201912","desc":""},"relativePath":"201912/20191204 Java vs. Python- Which should you choose.md","filePath":"[post].md"}'),p={name:"201912/20191204 Java vs. Python- Which should you choose.md"};function g(u,a,c,m,b,v){const l=i("Link");return r(),h("div",null,[a[15]||(a[15]=d(`<h1 id="java-与-python-你应该选择哪个" tabindex="-1">Java 与 Python：你应该选择哪个？ <a class="header-anchor" href="#java-与-python-你应该选择哪个" aria-label="Permalink to “Java 与 Python：你应该选择哪个？”">​</a></h1><blockquote><p>比较世界上最流行的两种编程语言，并在投票中让我们知道你喜欢哪一个。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201912/16/095025dppnl2lgtykgggkt.jpg" alt=""></p><p>让我们比较一下世界上两种最受欢迎、最强大的编程语言：Java 和 Python！这两种语言有巨大的社区支持和库来执行几乎任何编程任务，尽管选择编程语言通常取决于开发人员的场景。在比较和对比之后，请投票分享你的观点。</p><h3 id="是什么" tabindex="-1">是什么？ <a class="header-anchor" href="#是什么" aria-label="Permalink to “是什么？”">​</a></h3><ul><li><strong>Java</strong> 是一门通用面向对象的编程语言，主要用于开发从移动端到 Web 到企业级应用的各种应用。</li><li><strong>Python</strong> 是一门高级面向对象的编程语言，主要用于 Web 开发、人工智能、机器学习、自动化和其他数据科学应用。</li></ul><h3 id="创建者" tabindex="-1">创建者 <a class="header-anchor" href="#创建者" aria-label="Permalink to “创建者”">​</a></h3><ul><li><strong>Java</strong> 是由 James Gosling（Sun Microsystems）创造的。</li><li><strong>Python</strong> 是由 Guido van Rossum 创造的。</li></ul><h3 id="开源状态" tabindex="-1">开源状态 <a class="header-anchor" href="#开源状态" aria-label="Permalink to “开源状态”">​</a></h3><ul><li><strong>Java</strong> 是免费的，（大部分）开源，但商业用途除外。</li><li><strong>Python</strong> 对于所有场景都是免费、开源的。</li></ul><h3 id="平台依赖" tabindex="-1">平台依赖 <a class="header-anchor" href="#平台依赖" aria-label="Permalink to “平台依赖”">​</a></h3><ul><li><strong>Java</strong> 根据它的 WORA (“<ruby>一次编写，到处运行<rt>write once, run anywhere</rt></ruby>”)哲学，它是平台无关的。</li><li><strong>Python</strong> 依赖于平台。</li></ul><h3 id="编译或解释" tabindex="-1">编译或解释 <a class="header-anchor" href="#编译或解释" aria-label="Permalink to “编译或解释”">​</a></h3><ul><li><strong>Java</strong> 是一门编译语言。Java 程序在编译时转换为字节码，而不是运行时。</li><li><strong>Python</strong> 是一门解释性语言。Python 程序在运行时进行解释。</li></ul><h3 id="文件创建" tabindex="-1">文件创建 <a class="header-anchor" href="#文件创建" aria-label="Permalink to “文件创建”">​</a></h3><ul><li><strong>Java</strong>：编译后生成 <code>&lt;filename&gt;.class</code> 文件。</li><li><strong>Python</strong>：在运行期，创建 <code>&lt;filename&gt;.pyc</code> 文件。</li></ul><h3 id="错误类型" tabindex="-1">错误类型 <a class="header-anchor" href="#错误类型" aria-label="Permalink to “错误类型”">​</a></h3><ul><li><strong>Java</strong> 有 2 种错误类型：编译和运行时错误。</li><li><strong>Python</strong> 有 1 种错误类型：回溯（或运行时）错误。</li></ul><h3 id="静态或动态类型" tabindex="-1">静态或动态类型 <a class="header-anchor" href="#静态或动态类型" aria-label="Permalink to “静态或动态类型”">​</a></h3><ul><li><strong>Java</strong> 是静态类型。当初始化变量时，需要在程序中指定变量的类型，因为类型检查是在编译时完成的。</li><li><strong>Python</strong> 是动态类型。变量不需要在初始化时指定类型，因为类型检查是在运行时完成的。</li></ul><h3 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to “语法”">​</a></h3><ul><li><strong>Java</strong>：每个语句都需要以分号（<code>;</code> ）结尾，并且代码块由大括号（ <code>{}</code> ）分隔。</li><li><strong>Python</strong>：代码块通过缩进分隔（用户可以选择要使用的空格数，但在整个块中应保持一致）。</li></ul><h3 id="类的数量" tabindex="-1">类的数量 <a class="header-anchor" href="#类的数量" aria-label="Permalink to “类的数量”">​</a></h3><ul><li><strong>Java</strong>：在 Java 中的单个文件中只能存在一个公有顶级类。</li><li><strong>Python</strong>：Python 中的单个文件中可以存在任意数量的类。</li></ul><h3 id="代码多少" tabindex="-1">代码多少？ <a class="header-anchor" href="#代码多少" aria-label="Permalink to “代码多少？”">​</a></h3><ul><li><strong>Java</strong> 通常比 Python 要写更多代码行。</li><li><strong>Python</strong>通常比 Java 要写更少代码行。</li></ul><h3 id="多重继承" tabindex="-1">多重继承 <a class="header-anchor" href="#多重继承" aria-label="Permalink to “多重继承”">​</a></h3><ul><li><strong>Java</strong> 不支持多重继承（从两个或多个基类继承）。</li><li><strong>Python</strong> 支持多重继承，但由于继承复杂性、层次结构、依赖等各种问题，它很少实现。</li></ul><h3 id="多线程" tabindex="-1">多线程 <a class="header-anchor" href="#多线程" aria-label="Permalink to “多线程”">​</a></h3><ul><li><strong>Java</strong> 多线程可以支持同时运行的两个或多个并发线程。</li><li><strong>Python</strong> 使用全局解释器锁 （GIL），一次只允许运行单个线程（一个 CPU 核）。</li></ul><h3 id="执行速度" tabindex="-1">执行速度 <a class="header-anchor" href="#执行速度" aria-label="Permalink to “执行速度”">​</a></h3><ul><li><strong>Java</strong> 的执行时间通常比 Python 快。</li><li><strong>Python</strong> 的执行时间通常比 Java 慢。</li></ul><h3 id="hello-world" tabindex="-1">Hello world <a class="header-anchor" href="#hello-world" aria-label="Permalink to “Hello world”">​</a></h3><p>Java 的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public class Hello {</span></span>
<span class="line"><span>   public static void main([String][3][] args) {</span></span>
<span class="line"><span>      [System][4].out.println(&quot;Hello Opensource.com from Java!&quot;);</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Python 的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>print(&quot;Hello Opensource.com from Java!&quot;)</span></span></code></pre></div><h3 id="运行程序" tabindex="-1">运行程序 <a class="header-anchor" href="#运行程序" aria-label="Permalink to “运行程序”">​</a></h3><p><img src="https://opensource.com/sites/default/files/uploads/python-java-hello-world_0.png" alt="Java vs. Python" title="Java vs. Python"></p><p>要运行 java 程序 <code>Hello.java</code>，你需要先编译它，这将创建一个 <code>Hello.class</code> 文件。只需运行类名 <code>java Hello</code>。对于 Python，只需运行文件 <code>python3 helloworld.py</code>。</p><hr>`,41)),e("p",null,[a[1]||(a[1]=t("via: ",-1)),o(l,{href:"https://opensource.com/article/19/12/java-vs-python"},{default:n(()=>[...a[0]||(a[0]=[t("https://opensource.com/article/19/12/java-vs-python",-1)])]),_:1})]),e("p",null,[a[6]||(a[6]=t("作者：",-1)),o(l,{href:"https://opensource.com/users/architmodi"},{default:n(()=>[...a[2]||(a[2]=[t("Archit Modi",-1)])]),_:1}),a[7]||(a[7]=t(" 选题：",-1)),o(l,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[3]||(a[3]=[t("lujun9972",-1)])]),_:1}),a[8]||(a[8]=t(" 译者：",-1)),o(l,{href:"https://github.com/geekpi"},{default:n(()=>[...a[4]||(a[4]=[t("geekpi",-1)])]),_:1}),a[9]||(a[9]=t(" 校对：",-1)),o(l,{href:"https://github.com/wxy"},{default:n(()=>[...a[5]||(a[5]=[t("wxy",-1)])]),_:1})]),e("p",null,[a[12]||(a[12]=t("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[10]||(a[10]=[t("LCTT",-1)])]),_:1}),a[13]||(a[13]=t(" 原创编译，",-1)),o(l,{href:"https://linux.cn/"},{default:n(()=>[...a[11]||(a[11]=[t("Linux中国",-1)])]),_:1}),a[14]||(a[14]=t(" 荣誉推出",-1))])])}const k=s(p,[["render",g]]);export{f as __pageData,k as default}